from collections import deque

def girth(adj, n):
    best = float('inf')
    for s in range(n):
        dist = {s:0}
        parent = {s:-1}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    c = dist[u]+dist[v]+1
                    if c < best: best = c
    return best

def lcf_graph(offsets, n):
    adj = [set() for _ in range(n)]
    for i in range(n):
        adj[i].add((i+1)%n); adj[(i+1)%n].add(i)
    for i in range(n):
        off = offsets[i % len(offsets)]
        j = (i+off)%n
        adj[i].add(j); adj[j].add(i)
    return adj

adj = lcf_graph([-12,7,-7], 24)
print("girth:", girth(adj, 24))
edges = []
for u in range(24):
    for v in adj[u]:
        if u<v: edges.append((u,v))
print(len(edges), edges)
